update project_cost_items set strain = 'wild', note = '機器の据付と、配管・計装・受変電・建屋・工場の排水処理。化学プラントでは機器代の数倍になることが多い。燃料化設備1系列（乾燥菌体 年5万t）あたり。見積はない。従来型のバイオディーゼル工場の初期投資（年産能力1tあたり約300〜450ドル）や、大豆の溶媒抽出工場を手がかりに、湿った菌体の細胞破砕と乳化対策の分を上乗せした目安。プラントメーカーの概算で置き換える。脱水・油回収の工場の付帯設備。脂質分泌株では別の付帯設備を数える。', updated_at = now() where cost_item_id = 'cif_plant_utility';
