update project_cost_items set strain = 'wild', note = '循環させる溶媒（菌体1kgあたり3kg）を蒸留で回収する熱を、乾燥菌体1kgあたり1.5MJと置いた（熱の回収を含む目安、見積なし）。単価は蒸気1tあたり約5,000円（仮置き）。溶媒の種類で変わる。抽出溶媒を蒸留で回収する熱。脂質分泌株では数えない。', updated_at = now() where cost_item_id = 'cif_op_heat';
