update project_cost_items set strain = 'wild', note = '燃料化設備1系列の初期投資（41.5億円）の3%/年。初期投資の明細を書き換えたら、この額も合わせて直す。脱水・油回収の設備の保守。脂質分泌株では別の設備の保守を数える。', updated_at = now() where cost_item_id = 'cif_op_maintenance';
