insert into project_cost_tasks (cost_model_id, cost_task_id, scenario, group_label, label, count_driver, count_per_year, hours_per_occurrence, expense_per_occurrence, confidence, source_kind, owner, note, visibility, sort_order, strain, application, performer) values ('cm_p21_fuel_260914', 'ctf_sec_culture_operation', '中央培養', '菌体をつくる', '培養と溶媒相の回収の運転（1日分）', 'production_line', 300, null, 0, 'H', '推測', 'AMD（内部）', '脂質分泌株のときの培養の運転。1系列を1日動かすのに何時間の人手が要るかは未確認（分泌株でないときの行と同じ）。溶媒を抜いて工場へ送る作業を含む。杉浦先生に聞く（確認事項「燃料向けの培養の物量」）。', 'amd_internal', 11, 'secreting', null, 'sx');
insert into project_cost_tasks (cost_model_id, cost_task_id, scenario, group_label, label, count_driver, count_per_year, hours_per_occurrence, expense_per_occurrence, confidence, source_kind, owner, note, visibility, sort_order, strain, application, performer) values ('cm_p21_fuel_260914', 'ctf_sec_plant_operation', '共通', '脂肪酸を回収する', '溶媒からの脂肪酸の回収の運転（1日分）', 'plant_line', 300, 72, 0, 'H', '推測', 'AMD（内部）', '見積のない推測値。1系列を1日24時間動かすのに3人（72人時）とした置き方で、分泌株でないときの「脱水と油回収の運転」と同じ。確かめ方: 年間の工数を系列の数で割って、1工場あたりの人数に直して見る。', 'amd_internal', 21, 'secreting', null, 'sx');
insert into project_cost_notes (cost_model_id, cost_note_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cm_p21_fuel_260914', 'cnf_history_secreting', 'history', '脂質分泌株のスイッチ（2026-09-14）', 'まさ 2026-09-14「脂質を分泌できる株の開発も理論的には可能っていう話を杉浦先生からもらったので、コスト試算表を「脂質分泌株」のスイッチオンオフで切り替えられるようにしてほしい。脂質分泌株だと一気にコストが下がりそうな気がしてる」

**何を足したか**

枠の上端の「株」を「脂質分泌株」にすると、菌体を集めて壊して油を取り出す形から、菌体は槽に居たまま作った脂肪酸を培養液へ出させ、それを回収する形に切り替わる。第1段で数える単位が「菌体1kg」から「脂肪酸1kg」になり、脱水・細胞破砕・溶媒抽出・残渣の設備を数えず、代わりに閉鎖系の追加・培養液に重ねる溶媒・溶媒からの分離を数える。

**燃料1Lあたりの総コスト（円/L、残渣は発酵などで処理、排ガス利用可能は OFF）**

| 組み合わせ | 菌体から取り出す | 脂質分泌株 |
|---|---|---|
| 外部に委託・低位 | 11,260.0 | 3,994.9 |
| 外部に委託・基準 | 6,033.4 | 1,311.8 |
| 外部に委託・改善 | 4,053.3 | 835.2 |
| 自社で行う・基準 | 6,007.5 | 1,273.9 |

**なぜ下がるか、なぜ売価に届かないか**

下がるのは原料。菌体から取り出す形は、燃料1Lに菌体 18.0 kg が要り、そのうち燃料になるのは6%だけで、残り94%は残渣として捨てる。培地・CO2・窒素源はその捨てる分にも払っている。分泌株は、燃料1Lに脂肪酸 1.0 kg（＋入れ替える菌体 0.4 kg）で足りるので、原料が4,955.8 → 342.3 円/L になる。

下がらないのは培養設備。1系列（培養液 222.2 m³）が1年に作れる燃料は、菌体から取り出す形で 1,847.2 L、分泌株で 2,333.3 L と大きく変わらない。光合成が1日に固定できる炭素の量で決まるので、株を変えても培養の槽の数はあまり減らない（27,068 → 21,429 系列）。分泌株では、そこに閉鎖系の設備と溶媒相の充填が乗るので、培養設備の費用は1Lあたりむしろ上がる（443.1 → 693.4 円/L）。

**置いた数字**（すべて見積なし・研究室の実測か推測）

- 分泌速度 0.036 g/L/日（基準）: Kato ら 2017 の、生体に優しい溶媒を重ねた改変 Synechococcus が18日で0.64 g/L。低位0.010・改善0.074
- 培養液からの回収率 90%（基準）: 同じ報告の「出た脂肪酸の90%以上が溶媒側へ移った」
- 脂肪酸1kgあたりに入れ替える菌体 0.4 kg: Kato ら 2026 の「10日で自分の重さの0.9倍」を、約28日使い続けられるとした置き方
- 溶媒相は培養液の5%・1kg 500円、溶媒の補給 0.11 kg/kg-脂肪酸、溶媒からの分離の熱 20 MJ/kg-脂肪酸
- 閉鎖系の追加は、廃液処理のコスト試算の強化株と同じ額（排気の除菌・廃液の不活化・区画で 230万円/系列）

**確かめていないこと**

菌体をどれだけ長く使い続けられるか（いちばん長い報告で18日）、培養液1Lに1gも無い薄さから脂肪酸を取り出す設備の実際の費用、屋外や大きい槽での分泌速度、溶媒相を培養液の5%で足りるか（研究室の実験は40%）、カルタヘナ法の拡散防止措置で屋外の培養ができるか。', null, null, 'amd_internal', 21);
insert into project_cost_notes (cost_model_id, cost_note_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cm_p21_fuel_260914', 'cnf_caveat_secreting', 'caveat', '脂質分泌株の数字は、研究室の値からの置き方', '脂質分泌株の列は、まだ作られていない株を前提にした試算。分泌速度・培養液からの回収率・菌体を使い続けられる日数は研究室の小さい容器の値で、屋外や大きい槽での実測は無い。溶媒相の量と買値、溶媒から脂肪酸を分ける設備と熱は、見積のない推測値。

いちばん効くのは分泌速度。0.036 g/L/日 を半分にすると培養設備の系列数と初期投資が2倍になり、「脂肪酸1kgあたりに入れ替える菌体 0.4 kg」を2倍にすると原料が2倍になる。両方とも画面で動かして確かめられる。', null, null, 'amd_internal', 25);
insert into project_cost_questions (cost_model_id, cost_question_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cm_p21_fuel_260914', 'cqf_secretion_rate', '杉浦先生', '脂肪酸を培養液へ出させる株を作るとして、培養液1Lが1日に出せる量はどれくらいを見込めますか。また、同じ菌体を何日くらい使い続けられそうですか（入れ替えずに出し続けられる日数）。', '1日に出る量が培養設備の数（＝初期投資）を、使い続けられる日数が培地とCO2の量を決める。いまは研究室の報告（18日で0.64 g/L ＝ 0.036 g/L/日、10日で菌体の重さの0.9倍）から置いている。', null, null, 'open', null, null, 'caf_secretion_rate', 'amd_internal', 15);
insert into project_cost_questions (cost_model_id, cost_question_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cm_p21_fuel_260914', 'cqf_secretion_recovery', '杉浦先生', '培養液1Lに1gも入っていない薄さの脂肪酸を取り出す方法は、生体に優しい溶媒を重ねて受ける形と、酸を入れて分ける形と、樹脂に吸わせる形のどれが現実的ですか。', '培養液の量が莫大なので、取り出す方法で設備と薬剤の費用が桁で変わる。いまは溶媒を重ねて受ける形（研究室で実測がある唯一の形）で置いている。', null, null, 'open', null, null, 'caf_broth_recovery', 'amd_internal', 16);
commit;
